    "k441": "<span class=\"join-progress__dot\">4</span> <span class=\"join-progress__label\">Bevestigen</span>",
    "k442": "Stap 1 / 4 · Wie je bent",
    "k443": "Volledige naam",
    "k444": "E-mail",
    "k445": "Waar ben je gevestigd? <span class=\"hint\">optioneel</span>",
    "k446": "Stap 2 / 4 · Waarom Enki",
    "k447": "Waarom wil je een van de 300 zijn?",
    "k448": "Er zijn geen kosten en geen betaling — plaatsen worden verdiend, niet gekocht. Dit antwoord is waar de meeste aanvragen op worden beslist.",
    "k449": "Stap 3 / 4 · Wat je inbrengt",
    "k450": "Wat zou je bijdragen? <span class=\"hint\">kies alles wat van toepassing is</span>",
    "k451": "<input type=\"checkbox\" name=\"j-contrib\" value=\"Skills\" /> Vaardigheden",
