    "k478": "Stap 2 / 3 · Waarom je contact opneemt",
    "k479": "Wat brengt je bij ons? <span class=\"hint\">kies er één</span>",
    "k480": "<input type=\"radio\" name=\"c-reason\" value=\"I want to help build Enki\"> Ik wil helpen Enki op te bouwen",
    "k481": "<input type=\"radio\" name=\"c-reason\" value=\"Consultancy — policy (Advisory)\"> Consultancy voor een overheid, partij of instelling",
    "k482": "<input type=\"radio\" name=\"c-reason\" value=\"Consultancy — capital (Advisory)\"> Consultancy voor een fonds of investeerder",
    "k483": "<input type=\"radio\" name=\"c-reason\" value=\"Research / analysis (Institute)\"> Onderzoek of analyse van het Instituut",
    "k484": "<input type=\"radio\" name=\"c-reason\" value=\"Press / media\"> Pers &amp; media",
