    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Nooit kosten</span><span class=\"abadge\">{{svg2}}Eén van 300 zetels</span><span class=\"abadge\">Menselijke beoordeling bedoeld</span>",
